    const CAT_IMAGES = {"03 (1).png": "data:image/png;base64,", "07.png": "data:image/png;base64,", "01 (4).png": "data:image/png;base64,", "01 (3).png": "data:image/png;base64,", "05 (2).png": "data:image/png;base64,", "04 (2).png": "data:image/png;base64,"};

function resolveCatImg(name) { return CAT_IMAGES[name] || name; }
document.querySelectorAll('img[data-cat]').forEach((im) => {
  const raw = im.getAttribute('data-cat');
  im.decoding = 'async';
  if (CAT_IMAGES[raw]) im.src = CAT_IMAGES[raw];
});

document.addEventListener('DOMContentLoaded', () => {
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // ============================================================
  // 1. 音效：點擊時播放「貓叫聲.mp3」
  //    用 4 個 Audio 輪流播放，連點時聲音可以重疊、不會被切斷
  // ============================================================
  const MEOW_SRC = '貓叫聲.mp3';
  const MEOW_POOL_SIZE = 4;
  const MEOW_MIN_GAP = 120; // ms，避免同一次點擊被重複觸發
  const meowPool = [];
  let meowIdx = 0;
  let lastMeowAt = 0;
  let soundEnabled = true;

  for (let i = 0; i < MEOW_POOL_SIZE; i++) {
    const a = new Audio(MEOW_SRC);
    a.preload = 'auto';
    a.volume = 0.85;
    meowPool.push(a);
  }

  function playMeow() {
    if (!soundEnabled) return;
    const now = performance.now();
    if (now - lastMeowAt < MEOW_MIN_GAP) return;
    lastMeowAt = now;
    const a = meowPool[meowIdx];
    meowIdx = (meowIdx + 1) % MEOW_POOL_SIZE;
    try {
      a.currentTime = 0;
      const p = a.play();
      if (p && p.catch) p.catch(() => {});
    } catch (e) {
      console.warn('Meow error:', e);
    }
  }

  const soundToggleBtn = document.getElementById('soundToggleBtn');
  if (soundToggleBtn) {
    soundToggleBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      soundEnabled = !soundEnabled;
      const soundIcon = soundToggleBtn.querySelector('.sound-icon');
      const soundText = soundToggleBtn.querySelector('.sound-text');
      if (soundEnabled) {
        soundIcon.textContent = '🔊';
        soundText.textContent = '音效 ON';
        playMeow();
      } else {
        soundIcon.textContent = '🔇';
        soundText.textContent = '音效 OFF';
      }
    });
  }

  // ============================================================
  // 2. Canvas：漂浮腳印 + 點擊粒子
  //    優化：腳印/文字粒子都先畫成小圖(sprite)再 drawImage，
  //    不再每幀做 shadowBlur；用時間差(dt)讓 60Hz / 120Hz 速度一致；
  //    分頁在背景時暫停動畫。
  // ============================================================
  const canvas = document.getElementById('particleCanvas');
  const ctx = canvas.getContext('2d');
  const DPR = Math.min(window.devicePixelRatio || 1, 2);
  let width = 0;
  let height = 0;

  function resizeCanvas() {
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = Math.round(width * DPR);
    canvas.height = Math.round(height * DPR);
  }
  resizeCanvas();

  let resizeTimer = 0;
  window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(resizeCanvas, 100);
  });

  const pawColors = ['#f59e0b', '#f472b6', '#fbbf24', '#fdba74'];
  const ambientParticles = [];
  const burstParticles = [];
  const MAX_BURST = 260;

  // 畫一隻貓咪腳印：大肉墊 + 四顆趾頭
  function drawPaw(c, s) {
    c.beginPath();
    c.ellipse(0, s * 0.28, s * 0.52, s * 0.42, 0, 0, Math.PI * 2);
    c.fill();
    const toes = [[-0.66, -0.12, -0.5], [-0.24, -0.58, -0.15], [0.24, -0.58, 0.15], [0.66, -0.12, 0.5]];
    for (let i = 0; i < toes.length; i++) {
      const t = toes[i];
      c.beginPath();
      c.ellipse(t[0] * s, t[1] * s, s * 0.2, s * 0.28, t[2], 0, Math.PI * 2);
      c.fill();
    }
  }

  // 預先把「帶光暈的腳印」畫成離屏 canvas
  function makePawSprite(color, size) {
    const pad = 20;
    const box = Math.ceil(size * 2.4 + pad * 2);
    const off = document.createElement('canvas');
    off.width = Math.ceil(box * DPR);
    off.height = Math.ceil(box * DPR);
    const o = off.getContext('2d');
    o.scale(DPR, DPR);
    o.translate(box / 2, box / 2);
    o.fillStyle = color;
    o.shadowColor = color;
    o.shadowBlur = 12;
    drawPaw(o, size);
    return { img: off, box };
  }

  function makePaw(randomY) {
    const size = Math.random() * 22 + 14;
    const color = pawColors[Math.floor(Math.random() * pawColors.length)];
    const sprite = makePawSprite(color, size);
    return {
      x: Math.random() * width,
      y: randomY ? Math.random() * height : height + 60,
      speedY: Math.random() * 0.55 + 0.22,
      swayAmp: Math.random() * 28 + 10,
      swaySpeed: Math.random() * 0.012 + 0.004,
      phase: Math.random() * Math.PI * 2,
      rot: (Math.random() - 0.5) * 0.9,
      rotSpeed: (Math.random() - 0.5) * 0.004,
      alpha: Math.random() * 0.14 + 0.07,
      sprite: sprite.img,
      box: sprite.box
    };
  }

  const pawCount = reduceMotion ? 0 : Math.max(10, Math.min(22, Math.round(width / 70)));
  for (let i = 0; i < pawCount; i++) ambientParticles.push(makePaw(true));

  // 點擊粒子：每種「符號 x 顏色」只畫一次，之後重複使用
  const burstSymbols = ['福', '吉', '財', '旺', '喵', '💖'];
  const burstColors = ['#f59e0b', '#fbbf24', '#f472b6', '#ffffff'];
  const SPRITE_R = 24; // sprite 的基準半徑
  const glyphCache = {};
  function getGlyphSprite(symbol, color) {
    const key = symbol + color;
    if (glyphCache[key]) return glyphCache[key];
    const d = SPRITE_R * 2;
    const off = document.createElement('canvas');
    off.width = Math.ceil(d * DPR);
    off.height = Math.ceil(d * DPR);
    const o = off.getContext('2d');
    o.scale(DPR, DPR);
    o.fillStyle = color;
    o.beginPath();
    o.arc(SPRITE_R, SPRITE_R, SPRITE_R, 0, Math.PI * 2);
    o.fill();
    o.fillStyle = '#78350f';
    o.font = `bold ${SPRITE_R * 1.1}px 'Noto Sans TC', sans-serif`;
    o.textAlign = 'center';
    o.textBaseline = 'middle';
    o.fillText(symbol, SPRITE_R, SPRITE_R + 1);
    glyphCache[key] = off;
    return off;
  }

  function spawnCoinBurst(originX, originY) {
    if (reduceMotion) return;
    for (let i = 0; i < 20; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = Math.random() * 7 + 3;
      const symbol = burstSymbols[Math.floor(Math.random() * burstSymbols.length)];
      const color = burstColors[Math.floor(Math.random() * burstColors.length)];
      burstParticles.push({
        x: originX,
        y: originY,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed - 2.5,
        r: Math.random() * 12 + 10,
        sprite: getGlyphSprite(symbol, color),
        life: 1,
        decay: Math.random() * 0.025 + 0.015,
        rotation: Math.random() * Math.PI,
        rotSpeed: (Math.random() - 0.5) * 0.2
      });
    }
    if (burstParticles.length > MAX_BURST) {
      burstParticles.splice(0, burstParticles.length - MAX_BURST);
    }
  }

  let lastFrame = 0;
  let rafId = 0;

  function renderCanvas(t) {
    rafId = requestAnimationFrame(renderCanvas);
    // dt = 以 60fps 為 1 的時間倍率；上限 3 避免切回分頁時瞬移
    const dt = lastFrame ? Math.min((t - lastFrame) / 16.667, 3) : 1;
    lastFrame = t;

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

    for (let i = 0; i < ambientParticles.length; i++) {
      const p = ambientParticles[i];
      p.y -= p.speedY * dt;
      p.phase += p.swaySpeed * dt;
      p.rot += p.rotSpeed * dt;

      if (p.y < -60) {
        ambientParticles[i] = makePaw(false);
        continue;
      }
      const px = p.x + Math.sin(p.phase) * p.swayAmp;
      // 靠近畫面上下緣時淡入淡出
      const edge = Math.min(1, Math.max(0, Math.min(p.y + 60, height - p.y + 60) / 160));
      ctx.save();
      ctx.translate(px, p.y);
      ctx.rotate(p.rot + Math.sin(p.phase) * 0.25);
      ctx.globalAlpha = p.alpha * edge;
      ctx.drawImage(p.sprite, -p.box / 2, -p.box / 2, p.box, p.box);
      ctx.restore();
    }

    const drag = Math.pow(0.98, dt);
    for (let i = burstParticles.length - 1; i >= 0; i--) {
      const p = burstParticles[i];
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 0.24 * dt;
      p.vx *= drag;
      p.life -= p.decay * dt;
      p.rotation += p.rotSpeed * dt;

      if (p.life <= 0) {
        burstParticles.splice(i, 1);
        continue;
      }
      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rotation);
      ctx.globalAlpha = p.life;
      ctx.drawImage(p.sprite, -p.r, -p.r, p.r * 2, p.r * 2);
      ctx.restore();
    }
  }

  function startCanvas() {
    if (!rafId) {
      lastFrame = 0;
      rafId = requestAnimationFrame(renderCanvas);
    }
  }
  function stopCanvas() {
    cancelAnimationFrame(rafId);
    rafId = 0;
  }
  document.addEventListener('visibilitychange', () => {
    document.hidden ? stopCanvas() : startCanvas();
  });
  startCanvas();

  // ============================================================
  // 3. 3D 視差傾斜：用 requestAnimationFrame 合併 mousemove，
  //    並快取元素位置，避免每次移動都重新量版面
  // ============================================================
  function bindTilt(el, opts) {
    let rect = null;
    let raf = 0;
    let mx = 0;
    let my = 0;

    function apply() {
      raf = 0;
      if (!rect) rect = el.getBoundingClientRect();
      const x = mx - rect.left - rect.width / 2;
      const y = my - rect.top - rect.height / 2;
      const rotY = (x / (rect.width / 2)) * opts.max;
      const rotX = -(y / (rect.height / 2)) * opts.max;
      el.style.transform = opts.active(rotX.toFixed(2), rotY.toFixed(2));
    }

    el.addEventListener('mouseenter', () => { rect = el.getBoundingClientRect(); });
    el.addEventListener('mousemove', (e) => {
      mx = e.clientX;
      my = e.clientY;
      if (!raf) raf = requestAnimationFrame(apply);
    }, { passive: true });
    el.addEventListener('mouseleave', () => {
      if (raf) { cancelAnimationFrame(raf); raf = 0; }
      rect = null;
      el.style.transform = opts.rest;
    });
    window.addEventListener('scroll', () => { rect = null; }, { passive: true });
  }

  if (!reduceMotion) {
    const pedestalContainer = document.getElementById('pedestalContainer');
    const heroStageWrapper = document.querySelector('.hero-stage-wrapper');

    if (heroStageWrapper && pedestalContainer) {
      // 事件掛在外層，量位置也用外層；沿用原本的行為
      let rect = null;
      let raf = 0;
      let mx = 0;
      let my = 0;
      const rest = 'perspective(1000px) rotateX(0deg) rotateY(0deg) scale3d(1, 1, 1)';

      const apply = () => {
        raf = 0;
        if (!rect) rect = heroStageWrapper.getBoundingClientRect();
        const x = mx - rect.left - rect.width / 2;
        const y = my - rect.top - rect.height / 2;
        const rotateY = (x / (rect.width / 2)) * 14;
        const rotateX = -(y / (rect.height / 2)) * 14;
        pedestalContainer.style.transform =
          `perspective(1000px) rotateX(${rotateX.toFixed(2)}deg) rotateY(${rotateY.toFixed(2)}deg) scale3d(1.02, 1.02, 1.02)`;
      };

      heroStageWrapper.addEventListener('mouseenter', () => {
        rect = heroStageWrapper.getBoundingClientRect();
      });
      heroStageWrapper.addEventListener('mousemove', (e) => {
        mx = e.clientX;
        my = e.clientY;
        if (!raf) raf = requestAnimationFrame(apply);
      }, { passive: true });
      heroStageWrapper.addEventListener('mouseleave', () => {
        if (raf) { cancelAnimationFrame(raf); raf = 0; }
        rect = null;
        pedestalContainer.style.transform = rest;
      });
      window.addEventListener('scroll', () => { rect = null; }, { passive: true });
    }

    document.querySelectorAll('[data-tilt]').forEach((card) => {
      bindTilt(card, {
        max: 8,
        rest: 'perspective(800px) rotateX(0deg) rotateY(0deg) translateY(0)',
        active: (rx, ry) => `perspective(800px) rotateX(${rx}deg) rotateY(${ry}deg) translateY(-8px)`
      });
    });
  }

  // ============================================================
  // 4. 摸摸小貓與能量條
  // ============================================================
  const catAvatarElement = document.getElementById('catAvatarElement');
  const luckyPercentage = document.getElementById('luckyPercentage');
  const luckyProgressBar = document.getElementById('luckyProgressBar');
  const catSpeech = document.getElementById('catSpeech');
  const speechText = catSpeech.querySelector('.bubble-text');
  const petCatBtn = document.getElementById('petCatBtn');
  const heroCatImg = document.getElementById('heroCatImg');

  let currentLucky = 95;

  const catPhrases = [
    '「喵～今天所有的好事都會向你靠近！」',
    '「呼嚕呼嚕…好運能量正在持續充填！」',
    '「保持放鬆，你所焦慮的事情都會順利解決！」',
    '「靈動大眼為你照亮未來的方向 ✨」',
    '「招財肉球已為你踩下一整天的幸運足跡！」',
    '「氣場滿分！今天你是最幸運的人！」'
  ];

  function triggerPettingEffect(e) {
    // 這裡已經自己處理音效與粒子，不讓事件再冒泡到全頁點擊，避免重複觸發
    if (e && e.stopPropagation) e.stopPropagation();
    playMeow();

    let clickX;
    let clickY;
    if (e && e.clientX) {
      clickX = e.clientX;
      clickY = e.clientY;
    } else {
      const rect = catAvatarElement.getBoundingClientRect();
      clickX = rect.left + rect.width / 2;
      clickY = rect.top + rect.height / 2;
    }
    spawnCoinBurst(clickX, clickY);

    currentLucky = Math.min(100, currentLucky + 3);
    luckyPercentage.textContent = `${currentLucky}%`;
    luckyProgressBar.style.width = `${currentLucky}%`;

    speechText.textContent = catPhrases[Math.floor(Math.random() * catPhrases.length)];
    catSpeech.classList.add('active');

    catAvatarElement.style.transform = 'scale(0.94) rotate(-3deg)';
    setTimeout(() => {
      catAvatarElement.style.transform = '';
    }, 220);

    clearTimeout(catSpeech._timer);
    catSpeech._timer = setTimeout(() => {
      catSpeech.classList.remove('active');
    }, 3800);
  }

  if (catAvatarElement) catAvatarElement.addEventListener('click', triggerPettingEffect);
  if (petCatBtn) petCatBtn.addEventListener('click', triggerPettingEffect);

  // 點擊網頁任意位置：灑出粒子 + 貓叫聲
  document.addEventListener('click', (e) => {
    if (e.target.closest('#lightbox') || e.target.closest('.modal')) return;
    playMeow();
    spawnCoinBurst(e.clientX, e.clientY);
  });

  const floatToggleBtn = document.getElementById('floatToggleBtn');
  let isFloating = false;
  if (floatToggleBtn && catAvatarElement) {
    floatToggleBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      isFloating = !isFloating;
      playMeow();
      if (isFloating) {
        catAvatarElement.classList.add('is-floating');
        floatToggleBtn.innerHTML = '<span>🔄</span> 落地安頓';
        speechText.textContent = '「看！靈性飄浮，福氣環繞在整個空間！」';
      } else {
        catAvatarElement.classList.remove('is-floating');
        floatToggleBtn.innerHTML = '<span>🪄</span> 靈動飄浮視角';
        speechText.textContent = '「穩穩著地，守護你的每一刻踏實！」';
      }
      catSpeech.classList.add('active');
    });
  }

  // ============================================================
  // 5. 6 款造型切換（用 decode() 等圖片解碼完再淡入，換圖不卡）
  // ============================================================
  const moodBtns = document.querySelectorAll('.mood-btn');
  let moodToken = 0;
  moodBtns.forEach((btn) => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      const targetImg = btn.dataset.img;
      const targetPhrase = btn.dataset.phrase;

      playMeow();
      moodBtns.forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');

      if (heroCatImg) {
        const token = ++moodToken;
        heroCatImg.style.opacity = '0';
        heroCatImg.style.transform = 'scale(0.85) rotate(-6deg)';
        setTimeout(() => {
          if (token !== moodToken) return;
          const reveal = () => {
            if (token !== moodToken) return;
            heroCatImg.style.opacity = '1';
            heroCatImg.style.transform = 'scale(1) rotate(0deg)';
          };
          heroCatImg.src = resolveCatImg(targetImg);
          if (heroCatImg.decode) {
            heroCatImg.decode().then(reveal, reveal);
          } else {
            reveal();
          }
        }, 180);
      }

      speechText.textContent = targetPhrase;
      catSpeech.classList.add('active');

      const rect = catAvatarElement.getBoundingClientRect();
      spawnCoinBurst(rect.left + rect.width / 2, rect.top + rect.height / 2);
    });
  });

  // ============================================================
  // 6. 今日抽籤
  // ============================================================
  const fortunes = [
    { title: '🌸 滿滿好運降臨', icon: '✨', quote: '「小貓眨眼，好運湧現；心懷善念，所行皆順遂。」', color: '暖金琥珀黃', item: '招財貓爪掛飾', number: 'No. 88' },
    { title: '🐱 平安順遂萬事如意', icon: '🐾', quote: '「放慢呼吸，像小貓般優雅踩步，所有繁瑣雜事迎刃而解。」', color: '翡翠吉運綠', item: '靜心綠葉貓草', number: 'No. 16' },
    { title: '🧧 財運穩穩到來', icon: '💰', quote: '「雙手扣緊機遇，如同貓咪抱緊最愛的點心，豐收滿溢。」', color: '喜慶朱砂紅', item: '開運黃金鈴鐺', number: 'No. 66' },
    { title: '💡 靈感泉湧收穫滿載', icon: '🌟', quote: '「保持敏銳的好奇心，每一次探索都會化作驚喜的答案。」', color: '星芒奇蹟紫', item: '智慧琥珀水晶', number: 'No. 99' },
    { title: '💛 煩惱消散心情放鬆', icon: '🛌', quote: '「曬曬陽光、伸個懶腰，給自己充電，最好的機會就在轉角。」', color: '晴空舒心藍', item: '柔軟呼嚕小窩', number: 'No. 23' }
  ];

  const drawFortuneBtn = document.getElementById('drawFortuneBtn');
  const fortuneCard = document.getElementById('fortuneCard');
  const fortuneIcon = document.getElementById('fortuneIcon');
  const fortuneTitle = document.getElementById('fortuneTitle');
  const fortuneQuote = document.getElementById('fortuneQuote');
  const luckyColorBadge = document.getElementById('luckyColorBadge');
  const luckyItemBadge = document.getElementById('luckyItemBadge');
  const luckyNumberBadge = document.getElementById('luckyNumberBadge');

  if (drawFortuneBtn && fortuneCard) {
    drawFortuneBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      playMeow();
      fortuneCard.classList.add('shake');
      drawFortuneBtn.disabled = true;

      setTimeout(() => {
        fortuneCard.classList.remove('shake');

        const fortune = fortunes[Math.floor(Math.random() * fortunes.length)];
        fortuneIcon.textContent = fortune.icon;
        fortuneTitle.textContent = fortune.title;
        fortuneQuote.textContent = fortune.quote;
        luckyColorBadge.textContent = fortune.color;
        luckyItemBadge.textContent = fortune.item;
        luckyNumberBadge.textContent = fortune.number;

        const rect = fortuneCard.getBoundingClientRect();
        spawnCoinBurst(rect.left + rect.width / 2, rect.top + rect.height / 2);

        drawFortuneBtn.disabled = false;
      }, 450);
    });
  }

  // ============================================================
  // 7. 相片燈箱
  // ============================================================
  const lightbox = document.getElementById('lightbox');
  const lbImg = document.getElementById('lbImg');
  const lbCap = document.getElementById('lbCap');
  const lbCloseBtn = document.getElementById('lbCloseBtn');

  document.querySelectorAll('.cat-photo-card').forEach((card) => {
    card.addEventListener('click', (e) => {
      e.stopPropagation();
      const img = card.querySelector('img');
      lbImg.src = img.src;
      lbCap.textContent = card.dataset.caption;
      lightbox.classList.add('open');
      lightbox.setAttribute('aria-hidden', 'false');
      playMeow();
    });
  });

  function closeLightbox() {
    lightbox.classList.remove('open');
    lightbox.setAttribute('aria-hidden', 'true');
  }

  if (lbCloseBtn) lbCloseBtn.addEventListener('click', closeLightbox);
  if (lightbox) lightbox.addEventListener('click', (e) => {
    if (e.target === lightbox) closeLightbox();
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeLightbox();
  });

  // ============================================================
  // 8. 步驟三 Prompt 一鍵複製
  // ============================================================
  const copyPromptBtn = document.getElementById('copyPromptBtn');
  const promptCodeText = document.querySelector('.prompt-code-text');

  if (copyPromptBtn && promptCodeText) {
    copyPromptBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      const textToCopy = promptCodeText.textContent.trim();

      const textarea = document.createElement('textarea');
      textarea.value = textToCopy;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand('copy');
      document.body.removeChild(textarea);

      playMeow();
      const orig = copyPromptBtn.textContent;
      copyPromptBtn.textContent = '✓ 已複製指令！';
      copyPromptBtn.style.background = '#27c93f';
      copyPromptBtn.style.borderColor = '#27c93f';
      copyPromptBtn.style.color = '#fff';

      setTimeout(() => {
        copyPromptBtn.textContent = orig;
        copyPromptBtn.style.background = '';
        copyPromptBtn.style.borderColor = '';
        copyPromptBtn.style.color = '';
      }, 2000);
    });
  }

  // ============================================================
  // 9. 背景音樂（內建 bgm.mp3：小貓呼嚕聲）
  // ============================================================
  const bgm = new Audio('bgm.mp3');
  bgm.loop = true;
  bgm.volume = 0.4;
  bgm.preload = 'auto';

  const musicBtn = document.getElementById('musicToggleBtn');
  const musicText = musicBtn.querySelector('.music-text');
  let userChoseMusic = false;

  function setMusicUI(on) {
    musicBtn.classList.toggle('playing', on);
    musicText.textContent = on ? '音樂 ON' : '音樂 OFF';
  }
  function startMusic() {
    const p = bgm.play();
    if (p && p.then) {
      p.then(() => setMusicUI(true)).catch(() => setMusicUI(false));
    } else {
      setMusicUI(true);
    }
  }
  function stopMusic() {
    bgm.pause();
    setMusicUI(false);
  }
  bgm.addEventListener('error', () => {
    musicText.textContent = '找不到 bgm.mp3';
  });

  musicBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    userChoseMusic = true;
    bgm.paused ? startMusic() : stopMusic();
  });

  // 先嘗試自動播放；若被瀏覽器擋下，就在第一次點擊或按鍵時開始
  startMusic();
  const firstGesture = () => {
    if (!userChoseMusic && bgm.paused) startMusic();
    document.removeEventListener('pointerdown', firstGesture);
    document.removeEventListener('keydown', firstGesture);
  };
  document.addEventListener('pointerdown', firstGesture);
  document.addEventListener('keydown', firstGesture);

  // ============================================================
  // 10. 導覽列高亮：快取各區塊位置 + rAF 節流，捲動時不再反覆量版面
  // ============================================================
  const navLinks = document.querySelectorAll('.nav-link');
  const sections = Array.from(document.querySelectorAll('section'));
  let sectionTops = [];
  let currentSection = null;
  let navTicking = false;

  function cacheSectionTops() {
    sectionTops = sections.map((sec) => ({
      id: sec.getAttribute('id'),
      top: sec.getBoundingClientRect().top + window.pageYOffset - 120
    }));
  }

  function updateNav() {
    navTicking = false;
    const y = window.pageYOffset;
    let current = '';
    for (let i = 0; i < sectionTops.length; i++) {
      if (y >= sectionTops[i].top) current = sectionTops[i].id;
    }
    if (current === currentSection) return;
    currentSection = current;
    navLinks.forEach((link) => {
      link.classList.toggle('active', link.getAttribute('href') === `#${current}`);
    });
  }

  window.addEventListener('scroll', () => {
    if (!navTicking) {
      navTicking = true;
      requestAnimationFrame(updateNav);
    }
  }, { passive: true });

  window.addEventListener('resize', () => { cacheSectionTops(); updateNav(); });
  window.addEventListener('load', () => { cacheSectionTops(); updateNav(); });
  cacheSectionTops();
});
